async function searchEbay(query) {
  const url = `https://www.ebay.com/sch/i.html?_nkw=${encodeURIComponent(query)}&LH_BIN=1&_udhi=100`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });

  return await browserjs(tabId, () => {
    const links = Array.from(document.querySelectorAll('a[href*="/itm/"]')).map(a => {
      const parent = a.closest('li, div.s-card');
      const text = parent ? parent.innerText.replace(/\n+/g, ' | ') : '';
      return {
        href: a.href,
        title: a.innerText.trim(),
        text: text.slice(0, 300)
      };
    }).filter(x => x.title.length > 5 && !x.title.toLowerCase().includes("shop on ebay"));
    return links.slice(0, 5);
  });
}

