const tabId = 787783793;

async function getListingDetails(itemId) {
  const url = `https://www.ebay.com/itm/${itemId}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });

  return await browserjs(tabId, () => {
    const title = document.querySelector('h1.x-item-title__mainTitle, h1')?.innerText?.trim();
    const price = document.querySelector('.x-price-primary, [data-testid="x-price-primary"]')?.innerText?.trim();
    const shipping = document.querySelector('[data-testid="ux-labels-values--shipping"], .ux-labels-values--shipping')?.innerText?.trim();
    const returns = document.querySelector('[data-testid="ux-labels-values--returns"], .ux-labels-values--returns')?.innerText?.trim();
    const seller = document.querySelector('.x-sellercard-atf__info__about-seller, [data-testid="str-title"]')?.innerText?.trim();
    const rating = document.querySelector('.ux-summary__count, .star-rating, [data-testid="reviews-ratings-cntr"]')?.innerText?.trim();

    // look for item specifics
    const specs = {};
    document.querySelectorAll('.ux-layout-section-evo__col, .ux-layout-section__item, dl.ux-labels-values').forEach(el => {
      const label = el.querySelector('dt, .ux-labels-values__labels')?.innerText?.trim();
      const val = el.querySelector('dd, .ux-labels-values__values')?.innerText?.trim();
      if (label && val) specs[label] = val;
    });

    // also search body text for dimensions and weight
    const bodyText = document.body.innerText;

    return {
      title,
      price,
      shipping,
      returns,
      seller,
      rating,
      specs,
      snippet: bodyText.slice(0, 1500)
    };
  });
}

const item1 = await getListingDetails("327240105269"); // Rockland Melbourne 20"
console.log("ITEM 1 (Rockland):", JSON.stringify(item1, null, 2));

